package studio.solocamera;

import android.graphics.*;

/** Lightweight, editable social CTA cards with authentic vector platform marks. */
final class EditorSocialTitles {
 static final String[] PLATFORMS={"YouTube","Facebook","Instagram","TikTok","LinkedIn","X","Threads","Twitch","WhatsApp","Telegram","Discord","Pinterest"};
 static final String[][] ACTIONS={{"Subscribe","Watch next","Like, comment & share"},{"Follow my page","Share this video","Join our community"},{"Follow for more","Save this post","Link in bio"},{"Follow for more","Watch the next video","Link in bio"},{"Connect with me","Follow for insights","Join the discussion"},{"Follow for updates","Share this post","Join the conversation"},{"Follow for more","Join the thread","Visit my profile"},{"Follow the channel","Watch live","Join the stream"},{"Message us","Join our channel","Get in touch"},{"Join our channel","Join the community","Message us"},{"Join our server","Join the community","Keep the conversation going"},{"Follow for ideas","Save this idea","Explore more ideas"}};
 static boolean social(int id){return id>=40&&id<76;}
 static void configure(EditorProject.Clip c,int id,long duration){int platform=(id-40)/3,variant=(id-40)%3;c.text=ACTIONS[platform][variant];c.designSubtitle=platform==10?"discord.gg/yourcommunity":platform==8?"Your contact or channel":platform==0?"@yourchannel":"@yourhandle";c.designEyebrow=PLATFORMS[platform];c.textBackground=variant==1?0xfff7f7f4:0xff121e2b;c.textColor=variant==1?0xff172838:0xfff7f7f4;c.designAccent=0xffffc857;c.font="font:inter";c.textSize=54;c.bold=true;c.alignment=0;c.textY=-.50;EditorTitlePresets.animate(c,duration,variant+1);}
 static Bitmap bitmap(EditorProject.Clip c,int width,int height){int id=c.titleDesign-1,platform=(id-40)/3,variant=(id-40)%3;float unit=width/1080f;int w=Math.max(2,Math.round(width*.84f)),h=Math.max(2,Math.min(Math.round(height*.48f),Math.round(250*unit)));Bitmap out=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(out);Paint paint=new Paint(3);float corner=variant==0?h*.5f:(float)c.backgroundRadius*unit;
  EditorTitleAnimation.begin(canvas,0);if(c.backgroundEnabled){paint.setColor(c.textBackground);canvas.drawRoundRect(0,0,w,h,corner,corner,paint);}EditorTitleAnimation.end(canvas);EditorTitleAnimation.begin(canvas,1);float diameter=Math.min(h*.66f,w*.18f),left=w*.045f,cy=h*.5f;paint.setColor(EditorSocialIcons.color(platform));if(variant==2)canvas.drawRoundRect(left,cy-diameter/2,left+diameter,cy+diameter/2,diameter*.23f,diameter*.23f,paint);else canvas.drawCircle(left+diameter/2,cy,diameter/2,paint);float inset=diameter*.22f;EditorSocialIcons.draw(canvas,platform,new RectF(left+inset,cy-diameter/2+inset,left+diameter-inset,cy+diameter/2-inset));
  EditorTitleAnimation.end(canvas);float x=left+diameter+w*.045f,available=w-x-w*.055f;float titleSize=c.textSize*unit;EditorTitleAnimation.begin(canvas,2);EditorTitleGraphics.draw(canvas,c,c.designEyebrow,x,h*.14f,available,titleSize*.30f,h*.16f,c.font,true,c.textColor,c.alignment);EditorTitleAnimation.end(canvas);EditorTitleAnimation.begin(canvas,3);float end=EditorTitleGraphics.draw(canvas,c,c.text,x,h*.35f,available,titleSize,h*.29f,c.font,c.bold,c.textColor,c.alignment);EditorTitleAnimation.end(canvas);EditorTitleAnimation.begin(canvas,4);EditorTitleGraphics.draw(canvas,c,c.designSubtitle,x,Math.min(end+titleSize*.10f,h*.72f),available,titleSize*.40f,h*.20f,c.font,false,c.textColor,c.alignment);
  EditorTitleAnimation.end(canvas);EditorTitleAnimation.begin(canvas,1);paint.setColor(c.designAccent);if(variant==1)canvas.drawRect(x,h*.9f,Math.min(w-w*.05f,x+available*.35f),h*.92f,paint);else if(variant==0)canvas.drawCircle(w-w*.045f,h*.5f,Math.max(1,h*.025f),paint);else canvas.drawRect(x,h*.9f,x+available*.18f,h*.915f,paint);EditorTitleAnimation.end(canvas);return out;
 }
}
